    INSERT INTO quizzes (id, title, description, difficulty, status, time_limit, created_at, updated_at, created_by) VALUES
  ('11111111-1111-1111-1111-111111111111', 'Vietnam Economic Zones - Basic Knowledge', 'Test your understanding of the fundamental concepts of Vietnam''s economic zones and their role in national development.', 'easy', 'published', 15, '2025-10-05 05:59:39.51964+00', '2025-10-05 05:59:39.51964+00', 'a0000000-0000-4000-8000-000000000001'),
  ('22222222-2222-2222-2222-222222222222', 'Industrial Parks and Export Processing Zones', 'Explore the characteristics and functions of Vietnam''s industrial parks and export processing zones.', 'medium', 'published', 20, '2025-10-05 05:59:39.51964+00', '2025-10-05 05:59:39.51964+00', 'a0000000-0000-4000-8000-000000000001'),
  ('33333333-3333-3333-3333-333333333333', 'Investment and Business in Economic Zones', 'Advanced knowledge about investment procedures, regulations, and business operations in Vietnam''s economic zones.', 'hard', 'published', 25, '2025-10-05 05:59:39.51964+00', '2025-10-05 05:59:39.51964+00', 'a0000000-0000-4000-8000-000000000001'),
  ('03fe0db3-094e-4136-b46e-a324043e7f2b', 'Bài kiểm tra 1', 'Mô tả cho bài kiểm tra 1', 'medium', 'published', NULL, '2025-10-16 14:55:26.215687+00', '2025-11-06 14:29:55.804344+00', 'a0000000-0000-4000-8000-000000000001'),
  ('d95b7152-4549-4abf-a308-ed945b497d09', 'Dong bang song Hong', 'Bài kiểm tra đồng bằng sông Hồng 1', 'easy', 'published', NULL, '2025-11-06 14:56:18.827884+00', '2025-11-08 05:46:52.881596+00', 'a0000000-0000-4000-8000-000000000001');
    INSERT INTO quiz_questions (id, quiz_id, question, explanation, allow_multiple_answers, order_index, created_at, updated_at) VALUES
  ('11111111-1111-1111-1111-111111111101', '11111111-1111-1111-1111-111111111111', 'What is the primary purpose of establishing economic zones in Vietnam?', 'Economic zones are established to attract foreign investment, promote exports, and create employment opportunities while developing specific industries and technologies.', FALSE, 1, '2025-10-05 05:59:39.51964+00', '2025-10-05 05:59:39.51964+00'),
  ('11111111-1111-1111-1111-111111111102', '11111111-1111-1111-1111-111111111111', 'Which of the following is one of the key economic zones in Southern Vietnam?', 'The Southern Key Economic Zone includes Ho Chi Minh City and surrounding provinces, forming Vietnam''s largest economic hub.', FALSE, 2, '2025-10-05 05:59:39.51964+00', '2025-10-05 05:59:39.51964+00'),
  ('11111111-1111-1111-1111-111111111103', '11111111-1111-1111-1111-111111111111', 'What benefits do companies typically receive in Vietnam''s economic zones?', 'Companies in economic zones enjoy various incentives including tax breaks, simplified customs procedures, and better infrastructure to encourage investment and growth.', TRUE, 3, '2025-10-05 05:59:39.51964+00', '2025-10-05 05:59:39.51964+00'),
  ('11111111-1111-1111-1111-111111111104', '11111111-1111-1111-1111-111111111111', 'Which year marked a significant milestone in Vietnam''s economic zone development policy?', '2006 was significant as it marked the implementation of comprehensive regulations for economic zones, accelerating their development nationwide.', FALSE, 4, '2025-10-05 05:59:39.51964+00', '2025-10-05 05:59:39.51964+00'),
  ('11111111-1111-1111-1111-111111111105', '11111111-1111-1111-1111-111111111111', 'What role do coastal economic zones play in Vietnam''s economy?', 'Coastal economic zones leverage Vietnam''s strategic maritime location to facilitate international trade, develop shipping industries, and attract export-oriented manufacturing.', FALSE, 5, '2025-10-05 05:59:39.51964+00', '2025-10-05 05:59:39.51964+00'),
  ('22222222-2222-2222-2222-222222222201', '22222222-2222-2222-2222-222222222222', 'What is the main difference between an Industrial Park (IP) and an Export Processing Zone (EPZ)?', 'EPZs are specifically designed for export-oriented production with special customs privileges, while IPs can serve both domestic and export markets with more flexible operations.', FALSE, 1, '2025-10-05 05:59:39.51964+00', '2025-10-05 05:59:39.51964+00'),
  ('22222222-2222-2222-2222-222222222202', '22222222-2222-2222-2222-222222222222', 'Which sectors are commonly found in Vietnam''s industrial parks?', 'Vietnam''s industrial parks host diverse sectors including electronics, textiles, food processing, and automotive industries to create a balanced industrial ecosystem.', TRUE, 2, '2025-10-05 05:59:39.51964+00', '2025-10-05 05:59:39.51964+00'),
  ('22222222-2222-2222-2222-222222222203', '22222222-2222-2222-2222-222222222222', 'What infrastructure requirements must industrial parks meet?', 'Industrial parks must provide comprehensive infrastructure including power, water, waste treatment, roads, and telecommunications to support industrial operations.', TRUE, 3, '2025-10-05 05:59:39.51964+00', '2025-10-05 05:59:39.51964+00'),
  ('22222222-2222-2222-2222-222222222204', '22222222-2222-2222-2222-222222222222', 'Which province is known for having the highest concentration of industrial parks in Northern Vietnam?', 'Bac Ninh province has emerged as a major industrial hub in Northern Vietnam, hosting numerous industrial parks with significant foreign investment, particularly in electronics manufacturing.', FALSE, 4, '2025-10-05 05:59:39.51964+00', '2025-10-05 05:59:39.51964+00'),
  ('22222222-2222-2222-2222-222222222205', '22222222-2222-2222-2222-222222222222', 'What environmental requirements must industrial parks comply with?', 'Industrial parks must implement comprehensive environmental protection measures including waste treatment systems, emissions control, and environmental impact assessments.', FALSE, 5, '2025-10-05 05:59:39.51964+00', '2025-10-05 05:59:39.51964+00'),
  ('22222222-2222-2222-2222-222222222206', '22222222-2222-2222-2222-222222222222', 'What is the typical corporate income tax rate for enterprises in export processing zones?', 'Enterprises in EPZs typically enjoy preferential tax rates of 10% for 15 years, compared to the standard 20% rate, to encourage export-oriented production.', FALSE, 6, '2025-10-05 05:59:39.51964+00', '2025-10-05 05:59:39.51964+00'),
  ('33333333-3333-3333-3333-333333333301', '33333333-3333-3333-3333-333333333333', 'What documents are typically required for foreign investors to establish a business in an economic zone?', 'Foreign investors must provide comprehensive documentation including investment certificates, business licenses, capital proof, and project proposals to ensure compliance with Vietnamese regulations.', TRUE, 1, '2025-10-05 05:59:39.51964+00', '2025-10-05 05:59:39.51964+00'),
  ('33333333-3333-3333-3333-333333333302', '33333333-3333-3333-3333-333333333333', 'How long is the typical tax exemption period for priority sectors in economic zones?', 'Priority sectors such as high-tech, environmental protection, and R&D typically receive 4 years of tax exemption followed by 50% reduction for the next 9 years.', FALSE, 2, '2025-10-05 05:59:39.51964+00', '2025-10-05 05:59:39.51964+00'),
  ('33333333-3333-3333-3333-333333333303', '33333333-3333-3333-3333-333333333333', 'Which of the following are considered priority investment sectors in Vietnam''s economic zones?', 'Vietnam prioritizes high-tech industries, renewable energy, supporting industries, and R&D to drive technological advancement and sustainable development.', TRUE, 3, '2025-10-05 05:59:39.51964+00', '2025-10-05 05:59:39.51964+00'),
  ('33333333-3333-3333-3333-333333333304', '33333333-3333-3333-3333-333333333333', 'What is the minimum capital requirement for foreign-invested projects in most economic zones?', 'While requirements vary by sector and project type, many economic zones have minimum capital requirements around $2-5 million USD to ensure substantial investment and commitment.', FALSE, 4, '2025-10-05 05:59:39.51964+00', '2025-10-05 05:59:39.51964+00'),
  ('33333333-3333-3333-3333-333333333305', '33333333-3333-3333-3333-333333333333', 'What are the key advantages of the "One-Stop Shop" mechanism in economic zones?', 'The One-Stop Shop mechanism streamlines administrative procedures by consolidating multiple government services in one location, significantly reducing processing time and bureaucratic complexity.', TRUE, 5, '2025-10-05 05:59:39.51964+00', '2025-10-05 05:59:39.51964+00'),
  ('33333333-3333-3333-3333-333333333306', '33333333-3333-3333-3333-333333333333', 'Which international agreements does Vietnam participate in that benefit economic zone businesses?', 'Vietnam''s participation in CPTPP, EVFTA, and RCEP provides economic zone businesses with enhanced market access, reduced tariffs, and streamlined trade procedures across major markets.', TRUE, 6, '2025-10-05 05:59:39.51964+00', '2025-10-05 05:59:39.51964+00'),
  ('33333333-3333-3333-3333-333333333307', '33333333-3333-3333-3333-333333333333', 'What is the maximum land lease term for industrial projects in economic zones?', 'Industrial projects can typically lease land for up to 50 years with possible extensions, providing long-term stability for major investments and infrastructure development.', FALSE, 7, '2025-10-05 05:59:39.51964+00', '2025-10-05 05:59:39.51964+00'),
  ('25766b59-317f-4997-8971-26aa3244857d', 'd95b7152-4549-4abf-a308-ed945b497d09', 'Cảng biển lớn nhất của vùng là:', 'Đáp án: B
