-- ===========================================================================
-- Seed content (DATA ONLY — no DDL). Auto-generated from prod CSV exports.
-- ===========================================================================
-- Source: tmp/prod-export/{quizzes,quiz_questions,quiz_options}.csv
-- Generated by parsing the CSVs and emitting FK-ordered, escaped SQL.
-- Re-generate by re-running the node parser against updated CSVs.
--
-- SCOPE: general_settings (real values) + quizzes/quiz_questions/quiz_options.
-- Binary documents live in storage; uploaded by scripts/seed-local-content.sh.
--
-- ── Schema/seed separation ──────────────────────────────────────────────
-- This file contains ONLY INSERT/UPDATE/DELETE/TRUNCATE — no DDL. See
-- seed/README.md. Every block is guarded by to_regclass() so a missing/
-- renamed table logs a NOTICE and skips instead of crashing.
--
-- ── Idempotency ─────────────────────────────────────────────────────────
-- Re-runnable: upserts for settings, TRUNCATE...CASCADE for quizzes (FK order).
--
-- ── Ownership ───────────────────────────────────────────────────────────
-- All quizzes assigned to the LOCAL admin (created by 06-seed-users.sql):
--   a0000000-0000-4000-8000-000000000001  (admin@vngeo.local)
-- Prod created_by UUIDs are NOT imported (single-admin local-dev decision).
--
-- ── Prod data anomaly (fixed inline, flagged for prod) ──────────────────
-- Question 33333333-...-333333333302 ("How long is the typical tax exemption
-- period...") had quiz_id = 33333333-...-333333333303, which is itself a
-- QUESTION id ("priority investment sectors"), not a quiz. That FK target
-- does not exist, so the insert would fail. Corrected to quiz #3 (...333),
-- the only valid parent. Verify and fix in prod.
-- ===========================================================================
-- Note: created_by is inlined as the literal local admin UUID below (not a
-- psql :variable), so this file runs correctly under any psql invocation,
-- including non-interactive -f file mode from the seed-runner. ON_ERROR_STOP
-- is set by the runner via -v ON_ERROR_STOP=1.

BEGIN;

-- ===========================================================================
-- 1. general_settings — real values
-- ===========================================================================
-- Overrides the placeholder defaults inserted by init/01-general_settings.sql
-- with the real production values.
DO $$
BEGIN
  IF to_regclass('public.general_settings') IS NULL THEN
    RAISE NOTICE 'Skipping general_settings seed: table does not exist';
  ELSE
       'https://www.youtube.com/embed/hrUFFjGDPuI',
       'URL for the map drawing tutorial video'),
      ('feedback_form_url',
       'https://docs.google.com/forms/d/e/1FAIpQLSeVsSJ9TF16HYvhE5clUTuPXD9ZKo_pzsUyJRSks83oxlftUQ/viewform?usp=header',
       'URL for the feedback Google Form')
    ON CONFLICT (key) DO UPDATE SET
      value       = EXCLUDED.value,
      description = EXCLUDED.description,
      updated_at  = now();
    RAISE NOTICE 'Seeded general_settings (%) rows', (SELECT count(*) FROM general_settings);
  END IF;
END $$;

-- ===========================================================================
-- 2. quizzes + quiz_questions + quiz_options — prod data
-- ===========================================================================
-- TRUNCATE in FK order (children->parent) for a clean slate, then INSERT in
-- dependency order (parent->children). UUID PKs, so RESTART IDENTITY is a
-- no-op but harmless. created_by forced to 'a0000000-0000-4000-8000-000000000001' for RLS.
DO $$
BEGIN
  IF to_regclass('public.quizzes') IS NULL THEN
    RAISE NOTICE 'Skipping quiz seed: public.quizzes does not exist';
  ELSE
    TRUNCATE TABLE public.quiz_options  RESTART IDENTITY CASCADE;
    TRUNCATE TABLE public.quiz_questions RESTART IDENTITY CASCADE;
    TRUNCATE TABLE public.quizzes        RESTART IDENTITY CASCADE;

